def start_withp(words):
    """Write a function to match two words from a list of words starting with letter 'p'."""
    if isinstance(words, str):
        words = [words]
    found = []
    for item in words:
        if not isinstance(item, str):
            continue
        for token in item.split():
            if token[:1].lower() == "p":
                found.append(token)
                if len(found) == 2:
                    return tuple(found)
    return tuple(found)
